  ('31b74bda-9da7-4850-b46b-f282b6ed96d8', '7a4143df-0daf-47b0-ae68-331ca15421bb', 'Khuyến cáo của Phân hội Tăng huyết áp - Hội Tim mạch Quốc gia Việt Nam (VSH/VNHA) về Chẩn đoán & Điều trị Tăng huyết áp 2022 (Tóm tắt)', '[{"title": "Tăng huyết áp trong thai kỳ", "number": "3.6.6"}]'::jsonb, 'Bảng 15. Phân loại tăng huyết áp trong thai kỳ (52)', 'Eclampsia: seizure, severe headache, visual disturbance, epigastric pain. HELLP: hemolysis, elevated liver enzymes, low platelets.', ARRAY[29]::smallint[], ARRAY[31]::smallint[], 'Sản giật: co giật, đau đầu dữ dội, rối loạn thị giác, đau bụng, buồn nôn/nôn, thiểu niệu. HELLP: tán huyết, tăng men gan, giảm tiểu cầu.', 1),
  ('333ea474-2295-4549-8c29-9a1cb1b74f0b', '7691ed2c-7e41-4928-be64-7aeed7aaee75', 'Khuyến cáo của Phân hội Tăng huyết áp - Hội Tim mạch Quốc gia Việt Nam (VSH/VNHA) về Chẩn đoán & Điều trị Tăng huyết áp 2022 (Tóm tắt)', '[{"title": "Tăng huyết áp trong thai kỳ", "number": "3.6.6"}]'::jsonb, 'Bảng 15. Phân loại tăng huyết áp trong thai kỳ (52)', 'Eclampsia/severe preeclampsia/HELLP: treat immediately (SBP<160, DBP<105 mmHg), labetalol or nicardipine plus magnesium sulfate.', ARRAY[29]::smallint[], ARRAY[31]::smallint[], 'Sản giật/Tiền sản giật nặng/HELLP: ngay lập tức hạ HA, Labetalol hoặc Nicardipine và Magnesium sulfate.', 1),
  ('341bbbbd-f05c-4e69-b93c-24012b24d926', 'b1de1e97-2ff3-421c-aa72-918aca6e2cac', 'Khuyến cáo của Phân hội Tăng huyết áp - Hội Tim mạch Quốc gia Việt Nam (VSH/VNHA) về Chẩn đoán & Điều trị Tăng huyết áp 2022 (Tóm tắt)', '[{"title": "Chiến lược điều trị phối hợp thuốc", "number": "3.5"}]'::jsonb, 'Bảng 11. Chống chỉ định của các nhóm thuốc điều trị tăng huyết áp chính (1)', 'Carries forward the pre-computed contraindicated-drug-class map; full table on the GLOBAL reference node.', ARRAY[23]::smallint[], ARRAY[25]::smallint[], 'Chống chỉ định bắt buộc/tương đối theo nhóm thuốc.', 1),
  ('346ce8dd-8ae2-4d48-a005-51b66803c3fa', 'bb7efb96-febd-4bd2-8ea1-dbffffe15678', 'Khuyến cáo của Phân hội Tăng huyết áp - Hội Tim mạch Quốc gia Việt Nam (VSH/VNHA) về Chẩn đoán & Điều trị Tăng huyết áp 2022 (Tóm tắt)', '[{"title": "Tăng huyết áp trong thai kỳ", "number": "3.6.6"}]'::jsonb, 'Bảng 15. Phân loại tăng huyết áp trong thai kỳ (52)', 'Gestational hypertension: onset after week 20, resolving within 6 weeks postpartum.', ARRAY[29]::smallint[], ARRAY[31]::smallint[], 'THA khởi phát sau tuần thứ 20 của thai kỳ, và kéo dài < 6 tuần sau sinh.', 1),
  ('34b6b26f-7bda-4e86-8917-5f9e28df690e', '1cef1f75-b0ed-44e2-aa0a-76de0fefba78', 'Khuyến cáo của Phân hội Tăng huyết áp - Hội Tim mạch Quốc gia Việt Nam (VSH/VNHA) về Chẩn đoán & Điều trị Tăng huyết áp 2022 (Tóm tắt)', '[{"title": "Tăng huyết áp và Bệnh mạch vành", "number": "3.7.2"}]'::jsonb, 'Bảng 14. Khuyến cáo điều trị bằng thuốc cho các trường hợp tăng huyết áp cấp cứu cụ thể (51); xem thêm Bảng 19, Mục 3.7.2', 'ACS: target SBP<140 mmHg immediately; see Bảng 19 for hypertension-with-CAD strategy.', ARRAY[28]::smallint[], ARRAY[30]::smallint[], 'Trích Bảng 14; đối chiếu bổ sung Bảng 19, Mục 3.7.2.', 1),
  ('35acebc5-c7e3-af53-7727-6add2ab19df6', 'd49ed998-c9d4-c06f-9859-ebd4459f4457', 'Khuyến cáo của Phân hội Tăng huyết áp - Hội Tim mạch Quốc gia Việt Nam (VSH/VNHA) về Chẩn đoán & Điều trị Tăng huyết áp 2022 (Tóm tắt)', '[{"title": "Điều trị tăng huyết áp", "number": "III"}, {"title": "Ngưỡng huyết áp ban đầu cần điều trị và ranh giới đích điều trị tăng huyết áp", "number": "3.1"}]'::jsonb, 'Hình 2. Tóm tắt ngưỡng huyết áp ban đầu & đích huyết áp phòng khám ở THA người lớn', 'High-normal BP with high cardiovascular risk enters the medication-treatment pathway.', ARRAY[14]::smallint[], ARRAY[16]::smallint[], 'Tree 3 patch: high-risk HABTC is not lifestyle-only.', 1),
  ('36253f6e-47cc-17b0-67a0-ba033b7ffb08', '0da5ee04-82fe-8681-957d-0ab16678ad1f', 'Khuyến cáo của Phân hội Tăng huyết áp - Hội Tim mạch Quốc gia Việt Nam (VSH/VNHA) về Chẩn đoán & Điều trị Tăng huyết áp 2022 (Tóm tắt)', '[{"title": "Chẩn đoán tăng huyết áp", "number": "I"}, {"title": "Định nghĩa và phân loại tăng huyết áp", "number": "1.2"}]'::jsonb, 'Bảng 1. Chẩn đoán tăng huyết áp theo ngưỡng huyết áp đo tại phòng khám', 'Clinic BP thresholds for normal BP, high-normal BP, Grade 1 hypertension, Grade 2 hypertension, hypertensive emergency, and isolated systolic hypertension.', ARRAY[7]::smallint[], ARRAY[9]::smallint[], NULL, 2),
  ('388f61c8-3b07-7d1f-a5b0-f1235456e601', '619dadfb-5f0d-d2e4-bc1f-ea5f22452602', 'Khuyến cáo của Phân hội Tăng huyết áp - Hội Tim mạch Quốc gia Việt Nam (VSH/VNHA) về Chẩn đoán & Điều trị Tăng huyết áp 2022 (Tóm tắt)', '[{"title": "Điều trị tăng huyết áp", "number": "III"}, {"title": "Chiến lược điều trị tăng huyết áp", "number": "3.2"}]'::jsonb, 'Hình 3. Sơ đồ điều trị tăng huyết áp thiết yếu VSH/VNHA 2022', 'Monotherapy may be considered after lifestyle management when BP remains uncontrolled, or for age >=80 / frailty.', ARRAY[17]::smallint[], ARRAY[19]::smallint[], NULL, 1),
