  ('a1d0032e-8214-4b1e-8d64-bea37cbdf9d1', '7d45eddd-289f-4371-bfdc-ae485c019f19', 'Khuyến cáo của Phân hội Tăng huyết áp - Hội Tim mạch Quốc gia Việt Nam (VSH/VNHA) về Chẩn đoán & Điều trị Tăng huyết áp 2022 (Tóm tắt)', '[{"title": "Tăng huyết áp cấp cứu", "number": "3.6.5"}]'::jsonb, 'Bảng 14. Khuyến cáo điều trị bằng thuốc cho các trường hợp tăng huyết áp cấp cứu cụ thể (51)', 'General/malignant hypertensive emergency with or without TMA/AKI: MAP reduction 20-25% over several hours.', ARRAY[28]::smallint[], ARRAY[30]::smallint[], 'Trích Bảng 14, theo Van den Born và cộng sự (51).', 1),
  ('a2a058d6-e0b8-4397-b019-f30474fb10e5', '8d54c13f-fc80-466b-9a58-682772ad2b21', 'Khuyến cáo của Phân hội Tăng huyết áp - Hội Tim mạch Quốc gia Việt Nam (VSH/VNHA) về Chẩn đoán & Điều trị Tăng huyết áp 2022 (Tóm tắt)', '[{"title": "Tăng huyết áp và Bệnh thận mạn", "number": "3.7.4"}]'::jsonb, 'Bảng 22. Chiến lược điều trị tăng huyết áp có kèm bệnh thận mạn (4, 5)', 'If serum creatinine rises more than 30% within 4 weeks of starting/increasing a RAS-inhibitor, consider reducing the dose or stopping it (Class I).', ARRAY[35]::smallint[], ARRAY[37]::smallint[], 'Nếu creatinin huyết thanh tăng hơn 30% trong vòng 4 tuần, xem xét giảm liều hoặc ngừng thuốc ức chế RAS.', 1),
