  ('e1ec4d30-1ab7-4b7a-81d1-ee4eaaed290c', '68dfdcfb-e057-4d17-a4c4-5974309e2896', 'Khuyến cáo của Phân hội Tăng huyết áp - Hội Tim mạch Quốc gia Việt Nam (VSH/VNHA) về Chẩn đoán & Điều trị Tăng huyết áp 2022 (Tóm tắt)', '[{"title": "Tăng huyết áp trong thai kỳ", "number": "3.6.6"}]'::jsonb, 'Bảng 16. Khuyến cáo điều trị tăng huyết áp trong thai kỳ (2, 52)', 'Contraindicated: nicardipine. Avoid: atenolol, propranolol, nifedipine. Prefer: methyldopa/long-acting CCB.', ARRAY[30]::smallint[], ARRAY[32]::smallint[], 'Chống chỉ định Nicardipine; tránh Atenolol, Propranolol, Nifedipine; ưu tiên Methyldopa/CKCa tác dụng kéo dài.', 1),
  ('e208c1dc-0299-e113-595a-99a21277f8a0', '67ab35c9-30ea-85e4-ffb8-1a15cfb906e1', 'Khuyến cáo của Phân hội Tăng huyết áp - Hội Tim mạch Quốc gia Việt Nam (VSH/VNHA) về Chẩn đoán & Điều trị Tăng huyết áp 2022 (Tóm tắt)', '[{"title": "Chẩn đoán tăng huyết áp", "number": "I"}, {"title": "Định nghĩa và phân loại tăng huyết áp", "number": "1.2"}]'::jsonb, 'Bảng 1. Chẩn đoán tăng huyết áp theo ngưỡng huyết áp đo tại phòng khám', 'Clinic BP thresholds for normal BP, high-normal BP, Grade 1 hypertension, Grade 2 hypertension, hypertensive emergency, and isolated systolic hypertension.', ARRAY[7]::smallint[], ARRAY[9]::smallint[], NULL, 2),
  ('e267381a-ee55-46e2-9e0c-ed9bb2082127', 'be01e787-1928-47aa-b9d0-e52427bc0cd7', 'Khuyến cáo của Phân hội Tăng huyết áp - Hội Tim mạch Quốc gia Việt Nam (VSH/VNHA) về Chẩn đoán & Điều trị Tăng huyết áp 2022 (Tóm tắt)', '[{"title": "Tăng huyết áp trong thai kỳ", "number": "3.6.6"}]'::jsonb, 'Bảng 15. Phân loại tăng huyết áp trong thai kỳ (52)', 'Pre-existing hypertension: present before pregnancy or before week 20, persisting >6 weeks postpartum with proteinuria.', ARRAY[29]::smallint[], ARRAY[31]::smallint[], 'THA có trước khi mang thai hoặc trước tuần lễ thứ 20 của thai kỳ và tồn tại > 6 tuần sau sinh với protein niệu.', 1),
  ('e28b8597-d016-cf8d-1682-f3f8cfee0939', 'c2ecd9d5-6085-75cd-7e11-2eb129f1b06e', 'Khuyến cáo của Phân hội Tăng huyết áp - Hội Tim mạch Quốc gia Việt Nam (VSH/VNHA) về Chẩn đoán & Điều trị Tăng huyết áp 2022 (Tóm tắt)', '[{"title": "Điều trị tăng huyết áp", "number": "III"}, {"title": "Chiến lược điều trị tăng huyết áp", "number": "3.2"}]'::jsonb, 'Hình 3. Sơ đồ điều trị tăng huyết áp thiết yếu VSH/VNHA 2022', 'Two available medicines, from low dose to usual dose.', ARRAY[17]::smallint[], ARRAY[19]::smallint[], NULL, 1),
