  ('edc7107e-8ce4-4170-8606-67dbfc6eff5b', 'df97e26d-8c51-4ce5-912e-d985421cc2d1', 'Khuyến cáo của Phân hội Tăng huyết áp - Hội Tim mạch Quốc gia Việt Nam (VSH/VNHA) về Chẩn đoán & Điều trị Tăng huyết áp 2022 (Tóm tắt)', '[{"title": "Tăng huyết áp cấp cứu", "number": "3.6.5"}]'::jsonb, 'Mục 3.6.5. Tăng huyết áp cấp cứu', 'Without acute target-organ damage, this is urgent hypertension, usually treatable with oral therapy.', ARRAY[27]::smallint[], ARRAY[29]::smallint[], 'Bệnh nhân tăng HA đáng kể nhưng không có tổn thương cơ quan đích cấp tính được gọi là tăng huyết áp khẩn trương.', 1),
  ('eded1a7d-ec4e-9f8c-c6f6-07b33f3d5cd7', '732bb6a9-f802-9e67-8377-bec03ab0ccab', 'Khuyến cáo của Phân hội Tăng huyết áp - Hội Tim mạch Quốc gia Việt Nam (VSH/VNHA) về Chẩn đoán & Điều trị Tăng huyết áp 2022 (Tóm tắt)', '[{"title": "Điều trị tăng huyết áp", "number": "II"}]'::jsonb, 'Hình 2. Ngưỡng huyết áp khởi trị và đích điều trị theo tuổi, huyết áp và bệnh đồng mắc', 'Tree 3 age group routing, comorbidity routing, lifestyle action path, and treatment-target routing.', NULL, NULL, 'Digitized according to the approved Tree 3 diagram.', 1);
